+const IDENTIFIER = "[0-9A-Za-z-]+";
+const VERSION_PATTERN = new RegExp(
+  `^v?(0|[1-9]\\d*|\\d+)\\.(\\d+)\\.(\\d+)(?:-(${IDENTIFIER}(?:\\.${IDENTIFIER})*))?(?:\\+(${IDENTIFIER}(?:\\.${IDENTIFIER})*))?$`,
+);
+const NUMERIC = /^\d+$/;
+
 /** Parse a version string. See README.md for the accepted syntax. */
 export function parseVersion(text: string): Version {
-  throw new Error("not implemented");
+  const match = VERSION_PATTERN.exec(text.trim());
+  if (match === null) {
+    throw new Error(`invalid version: ${JSON.stringify(text)}`);
+  }
+  const [, major, minor, patch, prerelease] = match;
+  return {
+    major: Number(major),
+    minor: Number(minor),
+    patch: Number(patch),
+    prerelease: prerelease === undefined ? [] : prerelease.split("."),
+  };
+}
+
+function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
+  const aNumeric = NUMERIC.test(a);
+  const bNumeric = NUMERIC.test(b);
+  if (aNumeric && bNumeric) {
+    const aDigits = a.replace(/^0+(?=\d)/, "");
+    const bDigits = b.replace(/^0+(?=\d)/, "");
+    if (aDigits.length !== bDigits.length) {
+      return aDigits.length < bDigits.length ? -1 : 1;
+    }
+    return aDigits === bDigits ? 0 : aDigits < bDigits ? -1 : 1;
+  }
+  if (aNumeric !== bNumeric) {
+    return aNumeric ? -1 : 1;
+  }
+  return a === b ? 0 : a < b ? -1 : 1;
+}
